package verify

import (
	"encoding/json"
	"errors"
	"fmt"
	"os"
	"path/filepath"
	"regexp"
	"strings"

	"maragu.dev/maragudb/internal/reach"
)

// Requirement with a stable ID in /docs/requirements.md or /docs/deviations.md.
type Requirement struct {
	ID string
	// Text of the requirement, as written next to its ID.
	Text string
	// Source document, relative to the module root.
	Source string
}

// Kind of a requirement, from the prefix of its ID.
func (r Requirement) Kind() string {
	kind, _, _ := strings.Cut(r.ID, "-")
	return kind
}

// KillMatrix of the simulator mutants, generated by the mutant test of the simulator into
// [KillMatrixPath].
type KillMatrix struct {
	// Seeds tried in every cell before a mutant counts as undetected there.
	Seeds int `json:"seeds"`
	// Cells are the simulator configurations every mutant runs in.
	Cells   []string           `json:"cells"`
	Mutants []KillMatrixMutant `json:"mutants"`
}

// KillMatrixMutant is one mutant with its result in every cell.
type KillMatrixMutant struct {
	ID   string `json:"id"`
	Name string `json:"name"`
	// Replay is the mutant's name for `make replay MUTATION=...`.
	Replay      string             `json:"replay"`
	Description string             `json:"description"`
	Results     []KillMatrixResult `json:"results"`
}

// KillMatrixResult of a mutant in one cell.
type KillMatrixResult struct {
	Cell   string `json:"cell"`
	Status Status `json:"status"`
	// Seed of first detection and the Checkers that found it, when detected.
	Seed     uint64   `json:"seed,omitempty"`
	Checkers []string `json:"checkers,omitempty"`
	// Reason the cell cannot detect the mutant, when not detected or not applicable.
	Reason string `json:"reason,omitempty"`
}

// Status of a mutant in a cell.
type Status string

// Statuses.
const (
	Detected      Status = "detected"
	Undetected    Status = "undetected"
	NotApplicable Status = "not applicable"
)

// Detected reports whether any cell detects the mutant.
func (m KillMatrixMutant) Detected() bool {
	for _, r := range m.Results {
		if r.Status == Detected {
			return true
		}
	}
	return false
}

// KillMatrixPath relative to the module root.
const KillMatrixPath = "internal/sim/testdata/kill-matrix.json"

// Catalog of every ID that tests can declare: requirements, deviations, mutants, and reached
// states.
type Catalog struct {
	Requirements []Requirement
	KillMatrix   KillMatrix
	States       []reach.Declared
}

// IDs in the catalog.
func (c Catalog) IDs() map[string]bool {
	ids := map[string]bool{}
	for _, r := range c.Requirements {
		ids[r.ID] = true
	}
	for _, m := range c.KillMatrix.Mutants {
		ids[m.ID] = true
	}
	for _, s := range c.States {
		ids[string(s.State)] = true
	}
	return ids
}

// FindRoot of the module, from the working directory upwards.
func FindRoot() (string, error) {
	dir, err := os.Getwd()
	if err != nil {
		return "", err
	}
	for {
		if b, err := os.ReadFile(filepath.Join(dir, "go.mod")); err == nil && strings.HasPrefix(string(b), "module "+module+"\n") {
			return dir, nil
		}
		parent := filepath.Dir(dir)
		if parent == dir {
			return "", errors.New("verify: module root not found")
		}
		dir = parent
	}
}

// LoadCatalog from the documents and the kill matrix under the module root.
func LoadCatalog(root string) (Catalog, error) {
	var c Catalog
	for _, source := range []string{"docs/requirements.md", "docs/deviations.md"} {
		b, err := os.ReadFile(filepath.Join(root, source))
		if err != nil {
			return c, err
		}
		reqs, err := ParseRequirements(source, string(b))
		if err != nil {
			return c, err
		}
		c.Requirements = append(c.Requirements, reqs...)
	}
	b, err := os.ReadFile(filepath.Join(root, KillMatrixPath))
	if err != nil {
		return c, err
	}
	if err := json.Unmarshal(b, &c.KillMatrix); err != nil {
		return c, fmt.Errorf("verify: decoding %s: %w", KillMatrixPath, err)
	}
	c.States = reach.Declarations()
	return c, nil
}

var (
	idTag      = regexp.MustCompile("`((?:AC|INV|DEV)-[A-Z0-9][A-Z0-9.-]*)`")
	listItem   = regexp.MustCompile(`^(?:-|\d+\.)\s+`)
	boldTitle  = regexp.MustCompile(`^\s*(?:-|\d+\.)\s+\*\*(.+?)\*\*`)
	firstBold  = regexp.MustCompile(`\*\*(.+?)\*\*`)
	spaces     = regexp.MustCompile(`\s+`)
	validIDFor = map[string]*regexp.Regexp{
		"docs/requirements.md": regexp.MustCompile(`^(?:AC-\d+(?:\.\d+)?|INV-[A-Z][A-Z0-9-]*[A-Z0-9])$`),
		"docs/deviations.md":   regexp.MustCompile(`^DEV-\d+$`),
	}
)

// ParseRequirements finds the ID tags in a document, written as code spans such as `AC-1.2`
// after the text they name. In the deviations, the text is the bold title of the tag's line.
// In the requirements, it is the text between the previous tag on the line, or the start of the
// line, and the tag, after the bold title of the enclosing top-level list item.
func ParseRequirements(source, doc string) ([]Requirement, error) {
	valid := validIDFor[source]
	var reqs []Requirement
	seen := map[string]bool{}
	var context string
	for _, line := range strings.Split(doc, "\n") {
		if m := boldTitle.FindStringSubmatch(line); m != nil && !strings.HasPrefix(line, " ") {
			context = strings.TrimRight(m[1], ".:")
		} else if strings.HasPrefix(line, "#") {
			context = ""
		}
		start := 0
		for _, loc := range idTag.FindAllStringSubmatchIndex(line, -1) {
			id := line[loc[2]:loc[3]]
			if valid != nil && !valid.MatchString(id) {
				return nil, fmt.Errorf("verify: %s: malformed ID %s", source, id)
			}
			if seen[id] {
				return nil, fmt.Errorf("verify: %s: ID %s is defined twice", source, id)
			}
			seen[id] = true
			var text string
			if source == "docs/deviations.md" {
				if m := firstBold.FindStringSubmatch(line); m != nil {
					text = m[1]
				}
			} else {
				text = clean(line[start:loc[0]])
				if context != "" && (start > 0 || !boldTitle.MatchString(line) || strings.HasPrefix(line, " ")) {
					text = context + ": " + text
				}
			}
			reqs = append(reqs, Requirement{ID: id, Text: text, Source: source})
			start = loc[1]
		}
	}
	return reqs, nil
}

// clean markdown out of a fragment of a line.
func clean(s string) string {
	s = strings.TrimSpace(s)
	s = listItem.ReplaceAllString(s, "")
	s = strings.NewReplacer("**", "", "`", "", "|", " ").Replace(s)
	return strings.TrimSpace(spaces.ReplaceAllString(s, " "))
}
